L1:#!/usr/bin/env node
L2:/**
L3: * Seed the 11 canonical `region` entries into one target environment.
L4: *
L5: * Environment Templates (buildTemplate.js / installTemplate.mjs) cover content-TYPE
L6: * schema only — entries are a separate concern and have to be seeded per environment
L7: * after that environment's `region` content type exists (i.e. after installTemplate.mjs
L8: * has run against it).
L9: *
L10: * Idempotent — uses deterministic entry IDs (`region-<siteId>`) so re-running is safe.
L11: *
L12: * Usage:
L13: *   npm run seed:contentful-regions -- --target dev
L14: */
L15:
L16:import { checkEnv, createClient, log } from './_shared.mjs';
L17:
L18:const args = process.argv.slice(2);
L19:const getArg = (flag) => {
L20:  const i = args.indexOf(flag);
L21:  return i !== -1 ? args[i + 1] : null;
L22:};
L23:
L24:const TARGET = getArg('--target');
L25:
L26:if (!TARGET) {
L27:  log.error('--target <environmentId> is required.');
L28:  console.error('  Example: npm run seed:contentful-regions -- --target dev\n');
L29:  process.exit(1);
L30:}
L31:
