L50:  { siteId: 'ZimmermannME', label: 'Middle East', locale: 'en-AE' },
L51:];
L52:
L53:async function upsertEntry(client, environmentId, contentTypeId, entryId, fields) {
L54:  const localizedFields = Object.fromEntries(
L55:    Object.entries(fields).map(([fieldId, value]) => [fieldId, { [DEFAULT_LOCALE]: value }]),
L56:  );
L57:
L58:  let exists = true;
L59:  try {
L60:    await client.entry.get({ environmentId, entryId });
L61:  } catch (err) {
